def solve(path):
    """Simplify a Unix-style path.
    Handles both absolute and relative paths robustly.
    Arguments:
        path (str): the path string.
    Returns:
        str: the canonical simplified path.
    """
    # Determine whether the path is absolute (starts with '/')
    is_abs = path.startswith('/')
    # Split on '/', keep empty parts to correctly handle leading/trailing slashes
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            # empty component (caused by //) or current directory – skip
            continue
        if part == '..':
            if stack:
                stack.pop()
            else:
                # at root (for absolute) or at beginning of relative path – ignore
                continue
        else:
            stack.append(part)
    if is_abs:
        # Absolute path always starts with a single '/'
        result = '/' + '/'.join(stack)
        # Ensure root is just '/'
        return result if result != '' else '/'
    else:
        # Relative path: join components without leading slash
        return '/'.join(stack)

