def solve(matrix):
    """Return the determinant of an integer square matrix.
    Empty matrix -> 1. Non‑square matrices return 0.
    Uses exact arithmetic via fractions for robustness.
    """
    n = len(matrix)
    if n == 0:
        return 1
    # Verify square
    for row in matrix:
        if len(row) != n:
            return 0
    # For very small n, use direct formulas
    if n == 1:
        return matrix[0][0]
    if n == 2:
        a, b = matrix[0]
        c, d = matrix[1]
        return a * d - b * c
    # Use Fraction Gaussian elimination for exact integer result
    from fractions import Fraction
    A = [[Fraction(val) for val in row] for row in matrix]
    sign = 1
    for i in range(n):
        # Find pivot row
        pivot = i
        while pivot < n and A[pivot][i] == 0:
            pivot += 1
        if pivot == n:
            return 0
        if pivot != i:
            A[i], A[pivot] = A[pivot], A[i]
            sign = -sign
        # Eliminate rows below
        for j in range(i + 1, n):
            if A[j][i] == 0:
                continue
            factor = A[j][i] / A[i][i]
            for k in range(i, n):
                A[j][k] -= factor * A[i][k]
    det = sign
    for i in range(n):
        det *= A[i][i]
    # det is a Fraction that should be integral
    return int(det)

