def solve(a, b):
    """Levenshtein distance between strings a and b."""
    m, n = len(a), len(b)
    # Ensure the shorter string is b to use less space
    if n > m:
        a, b = b, a
        m, n = n, m
    # dp[j] = distance for a[:i] and b[:j]
    dp = list(range(n + 1))
    for i in range(1, m + 1):
        prev = dp[0]
        dp[0] = i
        for j in range(1, n + 1):
            cur = dp[j]
            if a[i - 1] == b[j - 1]:
                dp[j] = prev
            else:
                dp[j] = 1 + min(prev, dp[j], dp[j - 1])
            prev = cur
    return dp[n]

