def solve(matrix):
    """Return the determinant of a square integer matrix (Bareiss algorithm)."""
    n = len(matrix)
    if n == 0:
        return 1
    a = [row[:] for row in matrix]
    sign = 1
    prev = 1
    for k in range(n - 1):
