def solve(n, b):
    """Convert integer n to a string representation in base b (2 <= b <= 36).
    Uses digits 0-9 then a-z for values 10-35. Handles negative numbers with a leading '-'.
    """
    if not (2 <= b <= 36):
        raise ValueError('Base must be between 2 and 36')
    if n == 0:
        return '0'
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    neg = n < 0
    n = -n if neg else n
    result = []
    while n > 0:
        n, rem = divmod(n, b)
        result.append(digits[rem])
    if neg:
        result.append('-')
    return ''.join(reversed(result))

