def solve(nums):
    import bisect
    tails = []  # tails[i] = min ending value of an inc subseq of length i+1
    for x in nums:
        # find position to replace in tails
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
