def solve(s):
    n = len(s)
    if n == 0:
        return ''
    def expand(l, r):
        while l >= 0 and r < n and s[l] == s[r]:
            l -= 1
            r += 1
        return l + 1, r - l - 1
    best_s, best_l = 0, 1
    for c in range(n):
        for l, r in ((c, c), (c, c + 1)):
            st, ln = expand(l, r)
            if ln > best_l:
                best_s, best_l = st, ln
    return s[best_s:best_s + best_l]

