def solve(nums):
    """Return length of longest strictly increasing subsequence.
    Uses O(n log n) patience sorting algorithm.
    """
    import bisect
    if not nums:
        return 0
    tails = []  # tails[i] = smallest possible tail of an IS of length i+1
    for x in nums:
        # find insertion point (first >= x) for non-decreasing, but we need strictly increasing
        # so use bisect_left to replace first >= x
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

